import { describe, expect, test } from 'bun:test';
import { ed25519 } from '@noble/curves/ed25519';
import fixture from '../../../agent/tests/fixtures/wire_vectors.json';
import type { QuoteJson } from './contract';
import { borshFunding, borshQuote, borshSpot, digest, parseEd25519Key, verifyQuote } from './wire';

// Generated by contracts/perennia/examples/wire_vectors.rs from the contract's own types; the
// spot and funding signatures were accepted by post_spot / settle_funding on a real instance.
const hex = (b: Uint8Array) => Array.from(b, x => x.toString(16).padStart(2, '0')).join('');
const encode = { quote: borshQuote, spot: borshSpot, funding: borshFunding } as Record<string, (m: never) => Uint8Array>;

describe('wire parity with contracts/perennia', () => {
  test.each(fixture.vectors.map(v => [`${v.kind} ${v.digest_hex.slice(0, 8)}`, v] as const))('%s', (_name, v) => {
    const body = encode[v.kind](v.message as never);
    expect(hex(body)).toBe(v.borsh_hex);
    expect(hex(digest(v.domain, fixture.contract_id, body))).toBe(v.digest_hex);
  });

  test('the fixture public key matches the fixture secret key', () => {
    const pub = ed25519.getPublicKey(Uint8Array.from(fixture.agent_secret_key_hex.match(/../g)!.map(h => parseInt(h, 16))));
    expect(hex(parseEd25519Key(fixture.agent_public_key))).toBe(hex(pub));
  });

  test('quote signatures verify against the agent key, and nothing else does', () => {
    const quotes = fixture.vectors.filter(v => v.kind === 'quote');
    expect(quotes.length).toBeGreaterThan(0);
    for (const v of quotes) {
      const q = v.message as unknown as QuoteJson;
      expect(verifyQuote(fixture.contract_id, q, v.signature_b64, fixture.agent_public_key)).toBe(true);
      expect(verifyQuote('perennia.near', q, v.signature_b64, fixture.agent_public_key)).toBe(false);
      expect(verifyQuote(fixture.contract_id, { ...q, price: String(BigInt(q.price) + 1n) }, v.signature_b64, fixture.agent_public_key)).toBe(false);
      expect(verifyQuote(fixture.contract_id, q, v.signature_b64, 'ed25519:11111111111111111111111111111111')).toBe(false);
    }
  });
});
